// CDLTRISTARLookback returns how many leading bars [Core.CDLTRISTAR] consumes
// before its first value: called with startIdx 0, its first value is at that
// bar.
func (c *Core) CDLTRISTARLookback() (int, error) {
	lookback := c.cdltristarLookback()
	if lookback < 0 {
		return 0, BadParam
	}
	return int(lookback), nil
}

// CDLTRISTARDisplayShift returns how many bars ahead (positive) or behind
// (negative) of the bar that computed it a chart draws output outputIdx of
// [Core.CDLTRISTAR]. The values are never shifted.
//
// Every output of this function is drawn at its own bar, so the answer is 0.
//
// It takes the output's position among the outputs of [Core.CDLTRISTAR], from
// 0, and returns [BadParam] for an index that names no output.
func (c *Core) CDLTRISTARDisplayShift(outputIdx int) (int, error) {
	if outputIdx < 0 || outputIdx >= 1 {
		return 0, BadParam
	}
	return 0, nil
}

// CDLTRISTAR recognizes the Tristar pattern over bars startIdx through endIdx.
//
// A three-candle pattern of three consecutive doji where the middle doji is a
// star (its body gaps away from the first). Bullish or bearish reversal signal.
//
// Formula and more info at https://ta-lib.org/functions/cdltristar.
//
// Inputs, each at least endIdx+1 long:
//   - inOpen: Open price of each bar.
//   - inHigh: High price of each bar.
//   - inLow: Low price of each bar.
//   - inClose: Close price of each bar.
//
// Outputs, each at least as long as the values written (the input length always
// suffices):
//   - outInteger: +100 (bullish, star gapped down), -100 (bearish, star gapped
//     up), or 0 when no pattern. Both signs are emitted.
//
// Element k of each output is the value at bar BegIdx+k of the returned
// [OutRange], and BegIdx is at least [Core.CDLTRISTARLookback]: a range that
// ends before it returns NBElement 0.
//
// The error is [OutOfRangeStartIndex] or [OutOfRangeEndIndex] for a range
// outside 0 to [IndexMax] or ending before it starts, and [BadParam] for an
// input too short or an output empty or too short.
